 credit:{title:'Credit reports and scores',publisher:'Consumer Financial Protection Bureau',url:'https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/',note:'Reports, scores, checking your own information, and recognizing credit-repair scams.'},
 dispute:{title:'How to dispute an error on your credit report',publisher:'Consumer Financial Protection Bureau',url:'https://www.consumerfinance.gov/ask-cfpb/how-do-i-dispute-an-error-on-my-credit-report-en-314/',note:'Contact the reporting company and information provider, explain the error, and supply supporting documents.'},
