export const items=[{id:'compass',symbol:'✥',title:'The Budget Compass',text:'A home should leave room for the rest of your life.'},{id:'lens',symbol:'◈',title:'The Clear-Sight Lens',text:'Compare the details. Ask who benefits and what you are paying for.'},{id:'ledger',symbol:'▤',title:'The True Ledger',text:'Read the underlying report. Investigate errors with evidence.'},{id:'key',symbol:'⚿',title:'The First Key',text:'You earned a clearer next step, not a mortgage approval.'}];
const c=(label,to,detail='',set={})=>({label,to,detail,set});
export const episode={id:'first-key',version:1,title:'The First Key',estimatedMinutes:10,nodes:{
 letter:{speaker:'You · a new beginning',symbol:'✉',title:'A letter under the door.',text:[`Morning light slips through the shutters of your rented cottage. Outside, Hearthvale is waking: a cart rattles over cobblestones, a kettle whistles, and the market bell rings three times.`,`On the floor is an envelope. Your lease ends in three months. You can renew, or start thinking about somewhere of your own. You have imagined a garden, a room that can become anything, and walls you are allowed to paint. But the path from wanting a home to owning one has always felt like someone else’s map.`,`A second note is tucked inside. “Meet me by the path. Bring your questions. — Rowan.”`],choices:[c('Open the door.','rowan','You don’t have to know the way yet.')]},
 rowan:{speaker:'Rowan · the pathfinder',symbol:'✦',title:'Nobody starts with all the answers.',text:[`Rowan is sitting on the low stone wall, mending a satchel. “Before you ask: no, I don’t have a magic house in here. Mostly breadcrumbs.” They hand you a folded map.`,`“Today, we find out what matters to you, what your money needs to do, and which questions open the right doors. You can make mistakes here. You can turn back. That is what practice is for.”`,`You are playing a fictional household with $6,000 monthly take-home income and $18,000 saved. These are story numbers, not current market prices or a prediction of what you can borrow. What are you hoping a home will give you?`],choices:[c('A little stability.','purpose','A place to settle in.',{priority:'stability'}),c('Space for my next chapter.','purpose','Room for the life I’m building.',{priority:'space'}),c('More control over my future.','purpose','Understand my options before choosing.',{priority:'control'})]},
 purpose:{speaker:'Rowan · the pathfinder',symbol:'✦',title:'Put that reason in your satchel.',text:[`“Remember your answer,” Rowan says. “A lovely kitchen is very good at making people forget why they started.”`,`Two trails leave the cottage. One leads to Mira’s provision shop, where every adventure gets a budget. The other reaches the guides’ guild, where you can learn who belongs on your team. Visit them in either order.`,`“And if today ends with a plan to wait, that can be a fine ending too. Your adventure is not a race against somebody else’s.”`],choices:[c('Unfold the map.','@map','Two new destinations are open.')],complete:'cottage'},
 market:{speaker:'Mira · the provisioner',symbol:'◇',title:'The price on the sign.',text:[`Mira’s shop smells of oranges and fresh bread. Behind the counter hang travel packs of every size. You reach for the largest. She raises an eyebrow. “Everything fits in that one. Including the things you don’t need.”`,`She rolls out two home brochures. Willow Cottage shows $1,600 a month in bold letters. Lantern House shows $2,200. “Those are only the principal-and-interest payments in our fictional offers. Turn the brochures over.”`,`The quieter numbers tell the rest of the story. Look at the full monthly household cost before deciding which pack you want to carry.`],widget:'compare',source:'budget',choices:[c('Willow: keep more room in the budget.','budget-choice','Total housing budget: $2,400/month.',{home:'willow',housing:2400}),c('Lantern: I value the extra space.','budget-choice','Total housing budget: $3,300/month.',{home:'lantern',housing:3300})]},
 'budget-choice':{speaker:'Mira · the provisioner',symbol:'◇',title:'What is left for living?',text:[`Mira counts out six stacks of coins. “Your take-home income is $6,000. Everyday expenses and existing debt payments use $2,100. You also want to save $500 each month.”`,`She slides your chosen home’s costs across the counter. The remaining amount is {{margin}} a month. That money must absorb anything you did not anticipate.`,`“Extra space has value. So does being able to sleep when the refrigerator makes a strange noise. Which tradeoff can you live with?”`],widget:'monthly',source:'budget',choices:[c('Keep this choice and plan for surprises.','reserve','Your tradeoff follows you into the story.'),c('Look at the two homes again.','market','Nothing is committed yet.')]},
 reserve:{speaker:'Mira · the provisioner',symbol:'◇',title:'Pack for the unexpected.',text:[`Now Mira sets your savings on the counter: $18,000. In this story, $10,000 is earmarked for the down payment, $3,000 for other closing costs, and $1,000 for moving. That leaves $4,000.`,`Across the shop is a beautiful furniture set. You imagine it in your new living room. Mira puts an empty emergency pouch beside it. “Same coins. Two jobs.”`,`Choose how much of the remaining $4,000 to keep in the pouch. This is practice with a small fictional cushion, not a recommendation for your own reserve target.`],widget:'reserve',source:'budget',choices:[c('Pack my satchel.','market-end','Keep the chosen reserve and spend the rest on furniture.')]},
 'market-end':{speaker:'Mira · the provisioner',symbol:'◇',title:'You found the Budget Compass.',text:[`The little brass compass does not point north. It points toward a question: “Can I carry this and still live my life?”`,`Your emergency pouch now holds {{reserve}}. Your choice will matter when something unexpected happens. Mira wraps the compass in a cloth. “Take it with you. A bigger number on an approval letter doesn’t get to decide what feels comfortable in your kitchen.”`],lesson:'Include taxes, insurance, utilities, upkeep, and other applicable costs. Keep closing expenses and emergency money separate from the down payment.',source:'budget',item:'compass',complete:'market',choices:[c('Return to the trails.','@map','The guild or archive may be your next stop.')]},
 guild:{speaker:'Sage · the guild keeper',symbol:'⚑',title:'Choose your questions first.',text:[`The guild hall is full of maps. Some show houses; others show numbers. Nobody’s map shows everything. Sage pulls out a chair. “An agent can help with the property search and transaction. A lender works on financing. An inspector examines the home’s condition. Ask each person what they do, how they are paid, and where their work ends.”`,`A messenger bursts in carrying an ornate scroll. “The lowest payment in all Hearthvale!” he announces. Sage waits until the door closes. “What would you ask before trusting that claim?”`],source:'loans',choices:[c('What costs and loan features are behind that payment?','guild-wise','Compare the whole offer.',{question:'whole-offer'}),c('Can I stop shopping if this is the lowest payment?','guild-hasty','A smaller payment sounds like enough.',{question:'payment-only'})]},
 'guild-hasty':{speaker:'Sage · the guild keeper',symbol:'⚑',title:'The smallest number can hide a larger story.',text:[`Sage turns the scroll over. The payment leaves out several costs, and a ribbon covers the section about fees. “We haven’t learned enough to call this a bargain.”`,`“Ask for comparable Loan Estimates. Look at the loan type, interest rate, mortgage insurance, closing costs, and whether payments can change. Two offers only make sense beside each other when you know what is different.”`,`The messenger returns for his ribbon. You keep the questions.`],source:'loans',choices:[c('Ask for comparable offers.','guild-end','A useful question beats a confident guess.')]},
 'guild-wise':{speaker:'Sage · the guild keeper',symbol:'⚑',title:'A question worth carrying.',text:[`“Exactly.” Sage lays two blank frames side by side. “Ask lenders for Loan Estimates for the same loan features. Then compare the costs and terms. A low advertised payment is a starting point for questions.”`,`You jot down: What is included? What can change? What must I bring to closing? What are my alternatives?`,`“And receiving a Loan Estimate does not mean you are approved. Documents have jobs. Learn which job each one is doing.”`],source:'loans',choices:[c('Add those questions to my journal.','guild-end')]},
 'guild-end':{speaker:'Sage · the guild keeper',symbol:'◈',title:'You found the Clear-Sight Lens.',text:[`Sage gives you a small lens with a green rim. Through it, the tiny writing on the ornate scroll looks just as large as the headline.`,`“A good guide makes the details clearer,” Sage says. “They should leave you with more understanding, not fewer questions.”`,`Beyond the guild, the archive lantern flickers. The keeper is expecting someone, and the brass plate on the door has your fictional household’s name on it.`],lesson:'Request comparable Loan Estimates and review both upfront and ongoing costs. Ask questions before choosing a lender.',source:'loans',item:'lens',complete:'guild',choices:[c('Head back outside.','@map')]},
 archive:{speaker:'Ellis · the archivist',symbol:'▤',title:'You are more than a number.',text:[`The archive is quieter than you expected. Shelves of ledgers climb into warm darkness. Ellis brings down a slim folder. “People often ask for their score. I ask whether they have read the story underneath it.”`,`“A credit report contains account history and other reported information. A score uses information to estimate credit risk. Different scoring models can produce different numbers. Neither is a measure of your worth.”`,`You open a fictional training report. One entry catches your eye. Your receipt says a payment arrived on time. The report says it was late. What do you do?`],widget:'report',source:'credit',choices:[c('Gather the receipt and investigate the mismatch.','dispute','Follow the evidence.',{creditAction:'evidence'}),c('Pay the stranger promising to erase every bad mark.','shortcut','They claim they can guarantee a perfect record.',{creditAction:'shortcut'})]},
 shortcut:{speaker:'Ellis · the archivist',symbol:'▤',title:'The shortcut seller.',text:[`At the archive door, a stranger taps a silver stamp. “Perfect credit. Guaranteed.” Ellis asks him a simple question: “Including accurate negative information that is still allowed to be reported?” The stranger starts packing.`,`A promise is not evidence. Legitimate errors can be challenged. Accurate, current negative information cannot simply be erased by buying a service. Improving a record takes time; no one can promise your exact score gain.`,`Your receipt is still on the desk. That is a much better place to start.`],source:'credit',choices:[c('Return to the evidence.','dispute')]},
 dispute:{speaker:'Ellis · the archivist',symbol:'▤',title:'Correct the story with evidence.',text:[`You place the receipt beside the report and circle the mismatch. Ellis brings you a clean page. “Explain the specific error, and include copies of the evidence. Keep your originals.”`,`A dispute should go to the credit reporting company and the company that supplied the disputed information. If it looks like identity theft, there is a separate recovery path at IdentityTheft.gov.`,`In the adventure, your documented dispute has been prepared. It has not magically changed a real report or score. Investigations and real outcomes take time. What matters here is knowing how to start.`],lesson:'Identify the particular error, gather records, contact the reporting company and information provider, and keep copies of what you send.',source:'dispute',choices:[c('Keep the evidence, not the empty promise.','archive-end')]},
 'archive-end':{speaker:'Ellis · the archivist',symbol:'▤',title:'You found the True Ledger.',text:[`The repaired clasp clicks shut. Ellis has written three words inside the cover: Understand. Verify. Build.`,`“Your next credit adventure will go deeper: reading a report, handling errors, managing balances, making payments on time, and recognizing traps. There are useful actions here. There is no instant spell.”`,`Outside, the lights of Three-Door Lane are coming on. It is time to see what your choices look like in a real room—even if that room is still part of a story.`],source:'rebuild',item:'ledger',complete:'archive',choices:[c('Follow the lights to the houses.','@map')]},
 homes:{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'A house, and the life around it.',text:[`Nell meets you beside three front doors. One has a wide garden, one a sunny upstairs room, and one a workbench visible through the window. You remember what brought you here: {{priority}}.`,`“You chose {{homeName}} at the market. Let’s walk through it.” You pause in the doorway. The afternoon light is exactly right. For a moment, every question in your head disappears.`,`Then a drop of water lands on the windowsill. There is a dark patch above it. Nell watches your expression. “Still want to ask those questions?”`],source:'inspection',choices:[c('Have the condition investigated before deciding.','inspection','Bring in an independent inspector.',{repairAction:'inspect'}),c('The appraisal should tell me whether everything works.','appraisal','Isn’t that enough?',{repairAction:'appraisal'})]},
 appraisal:{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'Two different jobs.',text:[`“An appraisal and an inspection answer different questions,” Nell says. “The appraisal is about value for the lending process. An independent inspection examines condition.”`,`The sun shifts. The stain is still there. You do not need to panic, but you do need more information. Nell helps you prepare questions for the inspector: Where is the water coming from? What else should be checked? Should a specialist look at it?`],lesson:'An appraisal is not a substitute for an independent home inspection.',source:'inspection',choices:[c('Get the condition investigated.','inspection')]},
 inspection:{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'An unwelcome discovery.',text:[`For our fictional scenario, a qualified roofer follows up on the inspection and estimates $3,000 to fix the leak. Nell sets the written estimate on the table. The house still feels right. The repair does not disappear because of that.`,`You have {{reserve}} in the emergency pouch you packed earlier. Paying $3,000 from it would leave {{afterRepair}}. Your ongoing monthly breathing room is {{margin}}.`,`The seller might negotiate, but agreement is not guaranteed. The contract and deadlines matter. How do you want to respond?`],widget:'repair',source:'inspection',choices:[c('Ask the seller to address the repair.','negotiate','A request, not a guarantee.',{resolution:'negotiate'}),c('Accept the cost and look at what remains.','self-fund','See the effect of the earlier furniture choice.',{resolution:'self-fund'}),c('Explore stepping back under the contract.','step-back','Preserve the option to find a different home.',{resolution:'step-back'})]},
 negotiate:{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'A deal has two sides.',text:[`In this branch, the seller agrees to have the specified repair completed before closing, subject to the written agreement and verification. The tidy ending comes from this authored scenario; real sellers can say no.`,`Your emergency pouch stays at {{reserve}}. You still need to review the work and confirm your loan and closing requirements. A verbal promise does not finish the job.`,`“You didn’t win by demanding a perfect house,” Nell says. “You got the information and made a specific request.”`],source:'inspection',choices:[c('Carry the plan to the bridge.','homes-end')]},
 'self-fund':{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'Earlier choices have footsteps.',text:[`You run the numbers again. After this $3,000 repair, your pouch would hold {{afterRepair}}. {{reserveResult}}`,`“That is why we practiced at the market,” Nell says. “The furniture and the repair were spending the same money, even when you could only see one of them.”`,`You can reconsider before moving on. Choosing a home is not a test of whether you can defend your first answer.`],source:'budget',choices:[c('Reconsider how to handle the repair.','inspection','Try a different path.'),c('Keep this as my lesson and plan to prepare longer.','homes-end','An informed pause is a valid outcome.',{resolution:'prepare'})]},
 'step-back':{speaker:'Nell · the neighborhood guide',symbol:'⌂',title:'The courage to choose another door.',text:[`You ask Nell to explain the contract’s contingencies and deadlines before taking action. Whether you can cancel and recover a deposit depends on your actual agreement and circumstances.`,`In this story, your next step is to review those options and pause this purchase. There is disappointment. There is also room for another possibility.`,`Outside, the other two doors are still catching the sun. You have not failed to find a home. You have learned what this one asks of you.`],source:'inspection',choices:[c('Continue with a clearer plan.','homes-end')]},
 'homes-end':{speaker:'Rowan · the pathfinder',symbol:'✦',title:'You came back with better questions.',text:[`Rowan is waiting at the end of the lane. You show them the compass, lens, and ledger. None has made the world simple. Each has made it easier to understand.`,`“Ready for the bridge?” they ask. “There is one last choice waiting there.”`,`The lanterns along the stone rail begin to glow. Beyond them is the road toward your next chapter. You take a breath and open the map.`],complete:'homes',choices:[c('Return to the map.','@map','The lantern bridge is open.')]},
 bridge:{speaker:'Rowan · the pathfinder',symbol:'⚿',title:'The door beyond the bridge.',text:[`From the bridge, you can see the whole town: the cottage where you began, the provisioner’s awning, the archive lantern. It is a small distance on a map. It feels longer in your head.`,`“You could collect keys forever,” Rowan says. “But eventually the useful question is what you will do with what you learned.”`,`Choose a real-world next step. This does not commit you to a purchase, share your details, or submit an application.`],choices:[c('Understand my own numbers.','ending','Build a complete housing budget and review my reports.',{nextStep:'numbers'}),c('Prepare for a buyer or lender conversation.','ending','Bring the questions I collected.',{nextStep:'conversation'}),c('Give myself time to get ready.','ending','Make a preparation plan without rushing.',{nextStep:'prepare'})]},
 ending:{speaker:'Your adventure · chapter complete',symbol:'⚿',title:'The first key is understanding.',text:[`You turn the little brass key in your hand. It is not a deed, an approval, or a promise. It is the beginning of knowing what to ask—and the confidence to ask it.`,`{{endingText}}`,`Your personal field journal holds your choices, the facts behind them, and a next-step checklist. Take it with you. There are more doors ahead.`],complete:'gate',item:'key',ending:true,choices:[c('Open my field journal.','@journal','Save your takeaways and next steps.'),c('Explore the next adventure.','@series','A first look at The Credit Compass.')]}
}};
export const journalLessons={cottage:'I named what I want a home to make possible.',market:'I compared full monthly housing budgets and practiced keeping money for surprises.',guild:'I learned to ask for comparable loan offers and understand the details behind an advertised payment.',archive:'I practiced investigating a credit-report error with evidence instead of paying for a guaranteed quick fix.',homes:'I practiced responding to a repair finding, including negotiating or preparing longer.',gate:'I chose a next step I can take outside the adventure.'};
export function initialState(){return {version:1,started:false,done:[],inventory:[],vars:{priority:'stability',home:'willow',housing:2400,reserve:4000},node:'letter',location:'cottage',history:[],journal:[],player:{x:30,y:76},elapsed:0,ended:false};}
export function unlocked(state,loc){return loc.requires.every(id=>state.done.includes(id));}
export function choose(state,choice){if(choice.set)Object.assign(state.vars,choice.set);state.node=choice.to;return state;}
export function enter(state,node){if(node.complete&&!state.done.includes(node.complete))state.done.push(node.complete);if(node.item&&!state.inventory.includes(node.item))state.inventory.push(node.item);if(node.ending)state.ended=true;return state;}
